    {
        // Calculate pi using Leibniz formula (sufficient for 5 decimal places)
        double pi = 0;
        int terms = 1000000; // Enough terms for desired precision

        for (int i = 0; i < terms; i++)
        {
            pi += (i % 2 == 0 ? 1 : -1) / (2.0 * i + 1);
        }

        pi *= 4;

        // Round to 5 decimal places
        pi = Math.Round(pi, 5);


        Console.WriteLine($"Pi (rounded to 5 decimals): {pi}");


        // Convert the double to a long representation for XORing
