<h1>Chat App</h1>

<div id="chatbox"></div>

<input type="text" id="userinput" placeholder="Type your message...">
<button onclick="sendMessage()">Send</button>

<script>
  const chatbox = document.getElementById('chatbox');
  const userinput = document.getElementById('userinput');

  // Load the model
  let model;
  (async () => {
    model = await transformers.pipeline(
      "conversational",
      "facebook/blenderbot-400m-distill" // Specify the model
    );
    appendMessage("Bot", "Hi there! How can I help you today?"); // Initial bot message
  })();



  async function sendMessage() {
    const userMessage = userinput.value;
    if (userMessage.trim() === "") return; // Don't send empty messages

    appendMessage("You", userMessage);
    userinput.value = ""; // Clear the input field

    // Get the bot's response
    const botResponse = await getBotResponse(userMessage);
    appendMessage("Bot", botResponse);

    chatbox.scrollTop = chatbox.scrollHeight; // Scroll to the bottom
  }



  async function getBotResponse(userMessage) {
    try {      
      const response = await model([userMessage]);
      return response[0].generated_text;
    } catch (error) {
      console.error("Error generating bot response:", error);
      return "I'm having trouble understanding you right now. Please try again later.";
    }
  }

  function appendMessage(sender, message) {
    const messageDiv = document.createElement('div');
    messageDiv.innerHTML = `<strong>${sender}:</strong> ${message}`;
    chatbox.appendChild(messageDiv);
  }

</script>

</body>
</html>

```


