import string

class ChessBoard:
    def __init__(self):
        self.board = self.create_board()
        self.current_player = "white"

    def create_board(self):
        board = {}
        pieces = {
            "R": "Rook", "N": "Knight", "B": "Bishop", "Q": "Queen",
            "K": "King", "P": "Pawn"
        }
        for row in range(8):
            for col in range(8):
                piece = None
                if row == 0:  # Black back rank
                    piece = "b" + list(pieces.keys())[col] if col < 5 else "b" + list(pieces.keys())[7 - col]  # Account for mirrored back rank
                elif row == 1:
                    piece = "bP"
                elif row == 6:
                    piece = "wP"
                elif row == 7:
                    piece = "w" + list(pieces.keys())[col] if col < 5 else "w" + list(pieces.keys())[7 - col]
                board[(row, col)] = piece
        return board

    def print_board(self):
        print("  " + " ".join(string.ascii_lowercase[:8]))  # Column labels
        for row in range(8):
            print(8 - row, end=" ")
            for col in range(8):
                piece = self.board.get((row, col), "  ")  # Empty space if no piece
                print(piece, end=" ")
            print(8 - row)  # Row labels again
        print("  " + " ".join(string.ascii_lowercase[:8]))


    def move_piece(self, start, end):
      # Basic move validation - replace with full chess rules
        if self.board.get(start) is None or self.board.get(start)[0] != self.current_player[0]:
            return False  # No piece or wrong player

        self.board[end] = self.board[start]
        self.board[start] = None
        self.current_player = "black" if self.current_player == "white" else "white"
        return True


    def play(self):
        while True:
            self.print_board()
            while True:
                move = input(f"{self.current_player.capitalize()}'s move (e.g., a2 a4): ")
                try:
                    start_col, start_row, end_col, end_row = move.split()
                    start = (8 - int(start_row), string.ascii_lowercase.index(start_col))
                    end = (8 - int(end_row), string.ascii_lowercase.index(end_col))
                    if self.move_piece(start, end):
                        break
                    else:
                        print("Invalid move. Try again.")

                except (ValueError, IndexError):
                    print("Invalid input format. Use 'a2 a4' format.")

# Example usage
board = ChessBoard()
board.play()




```

