function updateHandle(e) {
  const rect = slider.getBoundingClientRect();
  const centerX = rect.left + radius;
  const centerY = rect.top + radius;
  const mouseX = e.clientX;
  const mouseY = e.clientY;

  const deltaX = mouseX - centerX;
  const deltaY = mouseY - centerY;
  let newRadius = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

  // Constrain to slider bounds
  newRadius = Math.min(radius, newRadius);



  const angle = Math.atan2(deltaY, deltaX);  // Use atan2 for correct quadrant
  const handleX = centerX + newRadius * Math.cos(angle) - handle.offsetWidth/2;  // Center the handle
  const handleY = centerY + newRadius * Math.sin(angle) - handle.offsetHeight/2; // Center the handle



