  handle.style.top =  (newRadius / radius * 100) + '%';
  handle.style.transform = `translate(-50%, -50%) translate(${newRadius * Math.cos(angle)}px, ${newRadius * Math.sin(angle)}px)`;


  const value = Math.round(newRadius / radius * 100);
  valueDisplay.textContent = value;


}

