  rand bit [31:0] data;

  `uvm_object_utils(transition_constraint)

  function new(string name = "transition_constraint");
    super.new(name);
  endfunction

  constraint c_num_transitions {
    $countones(data ^ prev(data)) == 5;
  }

  function void post_randomize();
    `uvm_info(get_name(), $sformatf("Data: 0x%h, Transitions: %0d", data, $countones(data ^ prev(data))), UVM_LOW)
  endfunction
endclass


