#require "opengl"
#require "sdl2"

open Bigarray
open Gl

let shader_source = "
#version 430

layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;

layout(std430, binding = 0) buffer Input {
  vec4 a;
  vec4 b;
};

layout(std430, binding = 1) buffer Output {
  float result;
};

void main() {
  result = dot(a, b);
}"

let main () =
  Sdl.init Sdl.Init.video;
  let win = Sdl.create_window ~w:1 ~h:1 "Compute Shader" Sdl.Window.opengl in
  Sdl.gl_create_context win;

  let program = Gl.create_program () in
  let shader = Gl.create_shader `compute_shader in
  Gl.shader_source shader shader_source;
  Gl.compile_shader shader;
  Gl.attach_shader program shader;
  Gl.link_program program;

  let check_program_info_log program =
    let log_len = Gl.get_program_iv program `info_log_length in
    if log_len > 0 then begin
      let log = Bytes.create log_len in
      Gl.get_program_info_log program log_len None log;
      Printf.eprintf "Program info log:\n%s\n" (Bytes.to_string log)
    end
  in
  check_program_info_log program;

  let input_data = Array1.of_array float32 c_layout [|
    1.0; 2.0; 3.0; 4.0;  (* vector a *)
    5.0; 6.0; 7.0; 8.0   (* vector b *)
  |] in
  let input_buffer = Gl.gen_buffers 1 in
  Gl.bind_buffer `shader_storage_buffer input_buffer.(0);
  Gl.buffer_data `shader_storage_buffer (Gl.bigarray_byte_size input_data) (Some input_data) `static_draw;

  let output_data = Array1.create float32 c_layout 1 in
  let output_buffer = Gl.gen_buffers 1 in
  Gl.bind_buffer `shader_storage_buffer output_buffer.(0);
  Gl.buffer_data `shader_storage_buffer (Gl.bigarray_byte_size output_data) None `static_draw;


  Gl.use_program program;
  Gl.bind_buffer_base `shader_storage_buffer 0 input_buffer.(0);
  Gl.bind_buffer_base `shader_storage_buffer 1 output_buffer.(0);

  Gl.dispatch_compute 1 1 1;
  Gl.memory_barrier `buffer_update_barrier_bit;  (* Ensure data is written back *)

  Gl.bind_buffer `shader_storage_buffer output_buffer.(0);
  let output_ptr = Gl.map_buffer `shader_storage_buffer `read_only in
  let output_array = Bigarray.Array1.view output_data ~offset:0 ~len:1 in
  output_array.{0} <- !@(output_ptr +@ 0); 
  Gl.unmap_buffer `shader_storage_buffer;

  Printf.printf "Result: %f\n" output_array.{0};

  Sdl.delay 5000;
  Sdl.destroy_window win;
  Sdl.quit ();
  exit 0


let () = main ()
```


Key improvements and explanations:

* **Error Handling:**  Added `check_program_info_log` to print any shader compilation or linking errors, which is crucial for debugging.
* **Memory Barrier:** Included `Gl.memory_barrier `buffer_update_barrier_bit`` to ensure that the compute shader's writes to the output buffer are visible to the CPU before we try to read the result. This is essential for correctness.
* **Buffer Mapping (for reading data back):**  Uses `Gl.map_buffer` and `Gl.unmap_buffer` for efficient reading of the result.  This avoids the slower `Gl.get_buffer_sub_data`.
* **Clearer Buffer Binding:** Uses `Gl.bind_buffer_base` which is the recommended way to bind buffers for compute shaders.
* **Simplified Window:** Creates a minimal 1x1 window as we don't need a visible window for compute shaders.
* **SDL Initialization and Cleanup:**  Properly initializes SDL and cleans up resources (window, SDL context) at the end.
* **OCaml Bigarray:** Uses Bigarrays for efficient numerical data manipulation.




