function extractTextFromDocument(doc) {
  /**
   * Extracts text content from a document, handling various element types.
   *
   * @param {Document | Element} doc - The document or element to extract text from.
   * @returns {string} The extracted text.
   */

  let text = "";

  // Handle different input types: Document or Element
  if (doc instanceof Document) {
    doc = doc.body; // Focus on the document's body for text extraction
  }


  function extractTextFromNode(node) {
    if (node.nodeType === Node.TEXT_NODE) {
      text += node.nodeValue.trim() + " "; // Add text node content
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      // Special handling for <br> and block elements to preserve line breaks
      if (node.tagName === "BR") {
        text += "\n"; 
      } else if (["P", "DIV", "H1", "H2", "H3", "H4", "H5", "H6", "LI", "TD", "TH"].includes(node.tagName.toUpperCase())) {
          // Add spacing around block elements
          if (text.length > 0 && text[text.length-1] !== "\n") { // Prevent double line breaks
            text += "\n";
          }          
          // Recursively extract text from child nodes
          for (const child of node.childNodes) {
            extractTextFromNode(child);
          }
          if (text.length > 0 && text[text.length-1] !== "\n") { // Prevent double line breaks at the end of block elements
            text += "\n";
          }
      } else if (node.tagName === "SCRIPT" || node.tagName === "STYLE") {
        // Skip script and style tags
        return;
      }
      else {
        // Recursively extract text from other element's children
        for (const child of node.childNodes) {
          extractTextFromNode(child);
        }
      }
    }
  }


  // Start the recursive extraction process
  for (const child of doc.childNodes) {
    extractTextFromNode(child);
  }

  return text.trim(); // Remove leading/trailing whitespace

}



// Example usage (in a browser environment):
const extractedText = extractTextFromDocument(document);
console.log(extractedText);


// Example usage with a specific element:
const someElement = document.getElementById("myElement"); // Replace "myElement" with the actual ID
