import java.util.List;
import java.util.NoSuchElementException;

public class SingleElementChecker {

    public static <T> T getSingleElement(List<T> list) {
        if (list == null) {
            return null; // Or throw an IllegalArgumentException if null is invalid input
        }

        try {
            return list.stream()
                    .reduce((a, b) -> {
                        throw new IllegalStateException("List contains more than one element");
                    })
                    .orElseThrow(NoSuchElementException::new); // Throw if the list is empty
        } catch (IllegalStateException e) {
            throw e; // Re-throw the custom exception for multiple elements
        }
    }


    public static void main(String[] args) {
        List<Integer> list1 = List.of(5);
        List<Integer> list2 = List.of(5, 6);
        List<Integer> list3 = List.of();
        List<String> list4 = List.of("hello");
        List<String> list5 = null;


        System.out.println(getSingleElement(list1)); // Output: 5
        try {
            System.out.println(getSingleElement(list2));
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage()); // Output: List contains more than one element
        }
        System.out.println(getSingleElement(list3)); // Output: null
        System.out.println(getSingleElement(list4)); // Output: hello
        System.out.println(getSingleElement(list5)); // Output: null



    }
}
