import java.net.http.HttpResponse;
import java.net.http.HttpResponse.BodyHandlers;

public class KubernetesLogReader {

    private final HttpClient httpClient;
    private final String kubernetesApiServerUrl;
    private final String token; // Kubernetes API token

    public KubernetesLogReader(String kubernetesApiServerUrl, String token) {
        this.kubernetesApiServerUrl = kubernetesApiServerUrl; // e.g., "https://kubernetes.default.svc.cluster.local"
        this.token = token;  // Replace with your actual token retrieval mechanism
        this.httpClient = HttpClient.newBuilder().build();
    }


    public String readPodLogs(String namespace, String podName, String containerName, boolean follow) throws IOException, InterruptedException {
        String url = String.format("%s/api/v1/namespaces/%s/pods/%s/log?container=%s&follow=%b",
                kubernetesApiServerUrl, namespace, podName, containerName, follow);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Authorization", "Bearer " + token) // Add authorization header
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            throw new RuntimeException("Failed to read logs. Status code: " + response.statusCode() + ", Body: " + response.body());
        }

        return response.body();
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        // Replace with your Kubernetes API server URL and token
        String apiServerUrl = "YOUR_KUBERNETES_API_SERVER_URL"; 
        String token = "YOUR_KUBERNETES_API_TOKEN";


        KubernetesLogReader logReader = new KubernetesLogReader(apiServerUrl, token);

        String namespace = "your-namespace"; // Replace with the actual namespace
        String podName = "your-pod-name"; // Replace with the actual pod name
        String containerName = "your-container-name"; // Replace with the actual container name (or leave empty/null for the main container)



        try {
            String logs = logReader.readPodLogs(namespace, podName, containerName, false); // Set 'follow' to true for streaming logs
            System.out.println(logs);
        } catch (RuntimeException e) {
            System.err.println("Error reading logs: " + e.getMessage());
        }

    }
}


