namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

class IpWhitelistMiddleware
{
    /**
     * Handle an incoming request.
     *
     * @param  \Closure(\Illuminate\Http\Request): (\Symfony\Component\HttpFoundation\Response)  $next
     */
    public function handle(Request $request, Closure $next): Response
    {
        $allowedIps = [
            '127.0.0.1', // Example IPs - replace with your actual allowed IPs
            '192.168.1.10',
            '::1', // IPv6 localhost
        ];

        // Get the client's IP address.  Handle cases where the user is behind a proxy.
        $clientIp = $request->ip();


        if (!in_array($clientIp, $allowedIps)) {
            // Option 1: Abort with a 403 Forbidden status
            abort(403, "Your IP address is not authorized.");


