```cpp
#include <highfive/H5File.hpp>
#include <highfive/H5DataSet.hpp>
#include <highfive/H5DataSpace.hpp>
#include <highfive/H5DataType.hpp>

struct Data {
    double v[3];
    int n;
};

int main() {
    try {
        // Create a new file using the default property lists.
        HighFive::File file("compound_example.h5", HighFive::File::ReadWrite | HighFive::File::Create | HighFive::File::Truncate);

        // Create a compound datatype for the Data struct
        HighFive::CompoundType dataType(sizeof(Data));

        // Add the 'v' member (array of 3 doubles)
        dataType.insertMember("v", offsetof(Data, v), HighFive::ArrayType(HighFive::AtomicType<double>(), 3));

        // Add the 'n' member (integer)
        dataType.insertMember("n", offsetof(Data, n), HighFive::AtomicType<int>());


        // Create dataspace.  Setting maximum size to NULL sets the maximum
        // size to be the current size.
        HighFive::DataSpace dataspace = HighFive::DataSpace({10}, {HighFive::DataSpace::UNLIMITED});

        // Create the dataset
        HighFive::DataSet dataset = file.createDataSet("data", dataType, dataspace);


        // Example of writing data:
        Data data[10];
        for (int i = 0; i < 10; ++i) {
            data[i].n = i;
            for (int j = 0; j < 3; ++j) {
                data[i].v[j] = i * 10.0 + j;
            }
        }
        dataset.write(data);


        // Example of reading data:
        Data read_data[10];
        dataset.read(read_data);

        for(int i=0; i<10; ++i){
            std::cout << "Data element " << i << ": n = " << read_data[i].n << ", v = {";
            for(int j=0; j<3; ++j){
                std::cout << read_data[i].v[j] << (j<2 ? ", " : "");
            }
            std::cout << "}" << std::endl;
        }


    } catch (HighFive::Exception& err) {
        // catch and print any HDF5 error
