// Define the different interest calculation strategies
class RegularInterest {
  calculate(balance) {
    return balance * 0.01; // 1% interest
  }
}

class GoldInterest {
  calculate(balance) {
    return balance * 0.02; // 2% interest
  }
}

class PlatinumInterest {
  calculate(balance) {
    return balance * 0.03; // 3% interest (plus a bonus!)
    const bonus = balance * 0.005; // Extra 0.5% bonus
    console.log("Congrats! You got a Platinum bonus of $" + bonus.toFixed(2));
    return balance * 0.03 + bonus;
  }

}


// Context class (BankAccount)
class BankAccount {
  constructor(accountNumber, balance, interestStrategy) {
    this.accountNumber = accountNumber;
    this.balance = balance;
    this.interestStrategy = interestStrategy;
  }

  setInterestStrategy(interestStrategy) {
    this.interestStrategy = interestStrategy;
  }

  calculateInterest() {
    return this.interestStrategy.calculate(this.balance);
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited $${amount}. New balance: $${this.balance.toFixed(2)}`);

     // Fun "gamified" feature: Give a small bonus for large deposits!
     if (amount >= 1000) {
      const bonus = amount * 0.001; // 0.1% bonus
      this.balance += bonus;
      console.log(`Wow! You got a bonus of $${bonus.toFixed(2)} for your large deposit!`);
    }
  }


  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew $${amount}. New balance: $${this.balance.toFixed(2)}`);
    } else {
      console.log("Insufficient funds!");
    }
  }

}


