#include <ap_int.h>
#include <hls_stream.h>

// Define data types and network parameters (adjust as needed)
typedef ap_fixed<16, 8> data_t;
const int IMG_SIZE = 28;
const int HIDDEN_UNITS = 128;
const int OUTPUT_UNITS = 10;

// Function to perform matrix-vector multiplication (used for both hidden and output layers)
void matmul(data_t A[HIDDEN_UNITS][IMG_SIZE * IMG_SIZE], data_t x[IMG_SIZE * IMG_SIZE], data_t y[HIDDEN_UNITS]) {
    for (int i = 0; i < HIDDEN_UNITS; i++) {
        data_t sum = 0;
        for (int j = 0; j < IMG_SIZE * IMG_SIZE; j++) {
#pragma HLS PIPELINE II=1
            sum += A[i][j] * x[j];
        }
        y[i] = sum;
    }
}


// Function to perform ReLU activation
void relu(data_t x[HIDDEN_UNITS], data_t y[HIDDEN_UNITS]) {
    for (int i = 0; i < HIDDEN_UNITS; i++) {
#pragma HLS PIPELINE II=1
        y[i] = (x[i] > 0) ? x[i] : 0;
    }
}


// Function to perform softmax activation (for output layer)
void softmax(data_t x[OUTPUT_UNITS], data_t y[OUTPUT_UNITS]) {
    data_t exp_sum = 0;
    data_t exp_x[OUTPUT_UNITS];

    for (int i = 0; i < OUTPUT_UNITS; i++) {
#pragma HLS PIPELINE II=1
        exp_x[i] = exp(x[i].to_float()); // Use floating-point for exp
        exp_sum += exp_x[i];
    }

    for (int i = 0; i < OUTPUT_UNITS; i++) {
#pragma HLS PIPELINE II=1
        y[i] = exp_x[i] / exp_sum;
    }
}

// Top-level function for MNIST inference
void mnist(data_t input_image[IMG_SIZE * IMG_SIZE], data_t output[OUTPUT_UNITS], data_t hidden_weights[HIDDEN_UNITS][IMG_SIZE * IMG_SIZE], data_t output_weights[OUTPUT_UNITS][HIDDEN_UNITS], data_t hidden_bias[HIDDEN_UNITS], data_t output_bias[OUTPUT_UNITS]) {

#pragma HLS INTERFACE m_axi port=input_image offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=output offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=hidden_weights offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=output_weights offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=hidden_bias offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=output_bias offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=return bundle=control



    data_t hidden_layer[HIDDEN_UNITS];
    data_t output_layer[OUTPUT_UNITS];


    // Hidden Layer Computation
    matmul(hidden_weights, input_image, hidden_layer);

    for(int i = 0; i < HIDDEN_UNITS; ++i) {
#pragma HLS PIPELINE II=1
        hidden_layer[i] += hidden_bias[i];
    }

    relu(hidden_layer, hidden_layer);


    // Output Layer Computation
    matmul(output_weights, hidden_layer, output_layer);

    for(int i = 0; i < OUTPUT_UNITS; ++i) {
#pragma HLS PIPELINE II=1
        output_layer[i] += output_bias[i];
    }

    softmax(output_layer, output);



}


```


Key improvements and explanations:

* **Data Type:**  Uses `ap_fixed<16,8>` for weights and activations. This fixed-point representation is generally more efficient in HLS than floating-point.  You can adjust the precision based on your accuracy requirements.
* **Pipelines:**  `#pragma HLS PIPELINE II=1` directives are added to the inner loops of `matmul`, `relu`, and `softmax`.  This is crucial for maximizing throughput.  II=1 means attempting to achieve one iteration per clock cycle.
* **Interfaces:** `#pragma HLS INTERFACE m_axi ...`  directives are used for the input and output arrays. This tells HLS to create efficient AXI interfaces for these arrays, enabling them to be accessed from memory. The `s_axilite` interface is used for control signals.
* **Array Partitioning:**  You might need to add array partitioning pragmas (e.g., `#pragma HLS ARRAY_PARTITION variable=A complete dim=1`) for large arrays like weights to improve performance. The optimal partitioning strategy depends on the target FPGA and the size of the arrays.
* **Function Inlining:**  Consider inlining smaller functions (like `relu`) if performance is critical. `#pragma HLS INLINE`


