function primes = efficientPrimeSearch(n)
% Efficiently finds all prime numbers less than or equal to n.
% Uses a vectorized Sieve of Eratosthenes.

    if n < 2
        primes = [];
        return;
    end

    isPrime = true(1, n);
    isPrime(1) = false;

    for p = 2:floor(sqrt(n))
