```rust
use std::iter::Iterator;

struct PrimeStream {
    current: u64,
}

impl PrimeStream {
    fn new() -> Self {
        PrimeStream { current: 2 }
    }

    fn is_prime(n: u64) -> bool {
        if n <= 1 {
            return false;
        }
        if n <= 3 {
            return true;
        }
        if n % 2 == 0 || n % 3 == 0 {
            return false;
        }
        let mut i = 5;
        while i * i <= n {
            if n % i == 0 || n % (i + 2) == 0 {
                return false;
            }
            i += 6;
        }
        true
    }
}


impl Iterator for PrimeStream {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let num = self.current;
            self.current += 1;

            if PrimeStream::is_prime(num) {
                return Some(num);
            }
        }
    }
}

fn main() {
    let prime_stream = PrimeStream::new();

    // Print the first 20 prime numbers
    for p in prime_stream.take(20) {
        print!("{} ", p);
    }
    println!();

    // Using filter and take_while to get primes less than 100
    let primes_under_100: Vec<u64> = PrimeStream::new()
        .take_while(|&p| p < 100)
        .collect();

    println!("Primes under 100: {:?}", primes_under_100);


    // Using find to find the first prime greater than 1000
    let first_prime_over_1000 = PrimeStream::new()
        .find(|&p| p > 1000);

    println!("First prime over 1000: {:?}", first_prime_over_1000);


}

```

