```typescript
class RNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;
  Wxh: number[][];
  Whh: number[][];
  Why: number[][];
  bh: number[];
  by: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;

    // Initialize weights and biases with random values
    this.Wxh = this.randomMatrix(hiddenSize, inputSize);
    this.Whh = this.randomMatrix(hiddenSize, hiddenSize);
    this.Why = this.randomMatrix(outputSize, hiddenSize);
    this.bh = this.randomArray(hiddenSize);
    this.by = this.randomArray(outputSize);
  }

  // Forward pass through the RNN
  forward(inputs: number[][]): number[][] {
    const hiddenStates: number[][] = [];
    let h: number[] = new Array(this.hiddenSize).fill(0); // Initial hidden state

    for (const input of inputs) {
      h = this.tanh(
        this.add(
          this.add(this.dot(this.Wxh, input), this.dot(this.Whh, h)),
          this.bh
        )
      );
      hiddenStates.push(h);
    }

    // Output layer
    const outputs: number[][] = hiddenStates.map((h) =>
      this.tanh(this.add(this.dot(this.Why, h), this.by))
    );

    return outputs;
  }


  // Helper functions for matrix and vector operations
  dot(a: number[][], b: number[] | number[][]): number[] {
    let result: number[] = [];
    if (Array.isArray(b[0])) { // Matrix multiplication (assuming correct dimensions)
       // Simplified matrix multiplication (assuming b is a column vector)
      for (let i = 0; i < a.length; i++) {
        let sum = 0;
        for (let j = 0; j < b.length; j++) {
             sum += a[i][j] * (b[j][0]);
        }
        result.push(sum);
      }
    } else { // Vector-matrix multiplication
      for (let i = 0; i < a.length; i++) {
        let sum = 0;
        for (let j = 0; j < a[i].length; j++) {
          sum += a[i][j] * b[j];
        }
        result.push(sum);
      }
    }

    return result;
  }

  add(a: number[], b: number[]): number[] {
    return a.map((val, i) => val + b[i]);
  }

  tanh(a: number[]): number[] {
    return a.map((val) => Math.tanh(val));
  }

  randomMatrix(rows: number, cols: number): number[][] {
    return Array(rows)
      .fill(null)
      .map(() => this.randomArray(cols));
  }

  randomArray(size: number): number[] {
    return Array(size)
      .fill(null)
      .map(() => Math.random() * 2 - 1); // Random values between -1 and 1
  }
}




// Example usage:
