class SpriteEditor {
  constructor(canvasId, spriteSheetImageSrc) {
    this.canvas = document.getElementById(canvasId);
    this.ctx = this.canvas.getContext('2d');
    this.spriteSheetImage = new Image();
    this.spriteSheetImage.src = spriteSheetImageSrc;  // E.g., "spritesheet.png"

    this.spriteWidth = 32;   // Default sprite dimensions
    this.spriteHeight = 32;
    this.selectedSpriteX = 0;
    this.selectedSpriteY = 0;

    this.spriteSheetImage.onload = () => {
      this.redraw();  // Draw once image is loaded
    };

    this.canvas.addEventListener('click', this.handleClick.bind(this)); // Bind for correct 'this'
    // Add more event listeners for other features like resizing, drag-and-drop, etc. as needed
  }


  redraw() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.ctx.drawImage(this.spriteSheetImage, 0, 0);

    // Draw selection rectangle
    this.ctx.strokeStyle = 'red';
    this.ctx.lineWidth = 2;
    this.ctx.strokeRect(this.selectedSpriteX * this.spriteWidth, 
                         this.selectedSpriteY * this.spriteHeight, 
                         this.spriteWidth, this.spriteHeight);
  }

  handleClick(event) {
    const rect = this.canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    this.selectedSpriteX = Math.floor(x / this.spriteWidth);
    this.selectedSpriteY = Math.floor(y / this.spriteHeight);

    this.redraw();

    // Display selected sprite coordinates or other information
    console.log(`Selected sprite: (${this.selectedSpriteX}, ${this.selectedSpriteY})`);


    // Get the image data of the selected sprite
    const spriteData = this.ctx.getImageData(
      this.selectedSpriteX * this.spriteWidth,
      this.selectedSpriteY * this.spriteHeight,
      this.spriteWidth,
      this.spriteHeight
    );

    // Example: Display pixel data (you can modify this to export, edit, etc.)
    //console.log(spriteData);  // Shows ImageData object

  }

  // ... Add methods for other features (resizing sprites, saving, loading, etc.)
  setSpriteDimensions(width, height) {
    this.spriteWidth = width;
    this.spriteHeight = height;
    this.redraw();
  }

  getSelectedSpriteData() { // Returns ImageData of selected sprite
    return this.ctx.getImageData(
      this.selectedSpriteX * this.spriteWidth,
      this.selectedSpriteY * this.spriteHeight,
      this.spriteWidth,
      this.spriteHeight
    );
  }


}



