use std::fmt::Display;

#[derive(Debug)]
pub enum MonthConversionError {
    InvalidMonthName,
}

impl Display for MonthConversionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            MonthConversionError::InvalidMonthName => write!(f, "Invalid month name provided."),
        }
    }
}


pub fn month_to_number<S: AsRef<str>>(month: S) -> Result<u8, MonthConversionError> {
    let month = month.as_ref().trim().to_lowercase();
    match month.as_str() {
        "january" | "jan" => Ok(1),
        "february" | "feb" => Ok(2),
        "march" | "mar" => Ok(3),
        "april" | "apr" => Ok(4),
        "may" => Ok(5),
        "june" | "jun" => Ok(6),
        "july" | "jul" => Ok(7),
        "august" | "aug" => Ok(8),
        "september" | "sep" => Ok(9),
        "october" | "oct" => Ok(10),
        "november" | "nov" => Ok(11),
        "december" | "dec" => Ok(12),
        _ => Err(MonthConversionError::InvalidMonthName),
    }
}



#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_month_names() {
        assert_eq!(month_to_number("January").unwrap(), 1);
        assert_eq!(month_to_number("january").unwrap(), 1);
        assert_eq!(month_to_number("Jan").unwrap(), 1);
        assert_eq!(month_to_number("jan").unwrap(), 1);
        assert_eq!(month_to_number("December").unwrap(), 12);
        assert_eq!(month_to_number("december").unwrap(), 12);
        assert_eq!(month_to_number("Dec").unwrap(), 12);
        assert_eq!(month_to_number("dec").unwrap(), 12);
        assert_eq!(month_to_number("May").unwrap(), 5);  // Single word month
        assert_eq!(month_to_number("  June  ").unwrap(), 6); // Test with whitespace
    }

    #[test]
    fn test_invalid_month_name() {
        let result = month_to_number("Jann");
        assert!(result.is_err());
        let err = result.unwrap_err();

        // Check the error type (optional, but useful)
        assert!(matches!(err, MonthConversionError::InvalidMonthName));

        // Check the error message
        assert_eq!(err.to_string(), "Invalid month name provided."); 
    }
}

```

Key improvements in this version:

* **Error Handling:** Uses `Result` and a custom error enum (`MonthConversionError`) for robust error handling. This is much better than panicking or returning a default value. The caller can now decide how to handle invalid input.
* **Case-Insensitive and Trimming:**  Converts the input to lowercase and trims whitespace to handle variations like "  January  " or "january".
* **Shortened Month Names:** Accepts both full and abbreviated month names (e.g., "January" or "Jan").
* **Clearer Error Messages:** The `Display` trait is implemented for the `MonthConversionError` enum, providing a user-friendly error message.
* **Thorough Testing:** Includes comprehensive unit tests to cover valid and invalid inputs, demonstrating how to check for both the error type and the error message.
* **Generics:** Uses generics (`<S: AsRef<str>>`) to accept various string types as input, making the function more flexible.


This improved version is more robust, user-friendly, and follows Rust's best practices for error handling and string manipulation. It's also well-tested, which is crucial for reliable code.

