            }
            if (!is.null(input$facet_var) && input$facet_var != "None") {
                p <- p + facet_wrap(as.formula(paste("~", input$facet_var)))
            }


        } else if (input$plot_type == "Boxplot") {
             p <- ggplot(mtcars, aes_string(x = input$xvar, y = input$yvar)) +
