function retryRequest(requestFn, retries = 3) {
  return new Promise((resolve, reject) => {
    requestFn()
      .then(resolve) // Resolve if the request is successful
      .catch((error) => {
        if (retries > 0) {
          console.warn(`Request failed, retrying (${retries} retries remaining)`);
          // Recursive call with reduced retry count
          retryRequest(requestFn, retries - 1)
            .then(resolve) // Resolve with the successful result of the retry
            .catch(reject);    // Reject if all retries fail
        } else {
          console.error("Request failed after multiple retries:", error);
          reject(error); // Reject if all retries are exhausted
        }
      });
  });
}


// Example usage (replace with your actual request function):

function mockRequest() {
  return new Promise((resolve, reject) => {
    const randomNumber = Math.random();
    if (randomNumber > 0.3) { // Simulate success with 70% probability
      resolve("Success!");
    } else {
      reject("Request failed!");
    }
  });
}


retryRequest(mockRequest)
  .then((result) => {
    console.log("Final result:", result);
  })
  .catch((error) => {
    console.error("Final error:", error);
  });



//  Alternative example with setTimeout to simulate asynchronous requests better:

function mockAsyncRequest() {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const randomNumber = Math.random();
      if (randomNumber > 0.3) {
        resolve("Success!");
      } else {
        reject("Request failed!");
      }
    }, 500); // Simulate a 500ms delay
  });
}

retryRequest(mockAsyncRequest)
  .then((result) => {
    console.log("Final result (async):", result);
  })
  .catch((error) => {
    console.error("Final error (async):", error);
  });

```


Key improvements and explanations:

1. **Clearer Recursive Structure:** The recursive call to `retryRequest` is now within the `.catch` block, making the logic more straightforward. The base case (no more retries) is also clearly handled.

2. **Error Handling:**  The code includes more robust error handling.  If all retries fail, the final `reject` call ensures the error is propagated up.

3. **Console Logging:**  `console.warn` and `console.error` provide better feedback during retries and final failure.

4. **Example Usage with Simulated Requests:** The included examples demonstrate how to use `retryRequest` with both synchronous and asynchronous mock request functions, making it easier to understand and test.  The `setTimeout` in `mockAsyncRequest` simulates a more realistic scenario.

5. **No `await`:** The code adheres to the requirement of not using `await`. The promise-based structure handles the asynchronicity.


