use regex::Regex;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::process::Command;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Regular expression to match YouTube URLs. Adjust as needed for your specific URL formats.
    let youtube_regex = Regex::new(r"(?x)
        (?:https?://)?                                       # Optional protocol
        (?:www\.)?                                          # Optional www
        (?:youtube\.com/watch\?v=|youtu\.be/)             # YouTube domains and paths
        ([a-zA-Z0-9_-]+)                                   # Video ID
    ")?;

    let file = File::open("urls.txt")?; // Replace "urls.txt" with your file name
    let reader = BufReader::new(file);

    let mut youtube_urls = Vec::new();
    let mut other_urls = Vec::new();

    for line in reader.lines() {
        let line = line?;
        let line = line.trim();

        if let Some(captures) = youtube_regex.captures(line) {
            let video_id = captures.get(1).unwrap().as_str();
            youtube_urls.push(format!("https://www.youtube.com/watch?v={}", video_id));
        } else if !line.is_empty() { // Skip empty lines
            other_urls.push(line.to_string());
        }
    }

    println!("YouTube URLs:");
    for url in &youtube_urls {
        println!("{}", url);

        // Download using yt-dlp
        let status = Command::new("yt-dlp") // Assumes yt-dlp is in your PATH
            .arg(url)
            // Add other yt-dlp options as needed, e.g.,
            // .arg("-f")
            // .arg("bestvideo[ext=mp4]+bestaudio[ext=m4a]/best[ext=mp4]/best")
            // .arg("-o")
            // .arg("%(title)s.%(ext)s")
            .status()?;

        if !status.success() {
            eprintln!("Error downloading {}: {}", url, status);
        }
    }

    println!("\nOther URLs:");
    for url in &other_urls {
        println!("{}", url);
    }

    Ok(())
}

```


**Explanation and Improvements:**

1. **Regex:** The regular expression is more robust and handles various YouTube URL formats (including shortened `youtu.be` links).  It also uses `(?x)` for extended mode to make the regex more readable. The regex now extracts the video ID to reconstruct a standardized URL.

2. **Error Handling:**  The code uses `Result` and the `?` operator for proper error handling. This is crucial for file I/O and running external commands.

3. **Empty Line Handling:** The code now skips empty lines in the input file.

4. **yt-dlp Options:** The code includes commented-out examples of how to add common `yt-dlp` options like format selection and output file naming.  Uncomment and customize these as needed.

5. **Clarity:** The code is better structured with comments and more descriptive variable names.



