```csharp
using System.Collections.Generic;
using System.Windows;
using System.Windows.Media;
using System.Windows.Shapes;

public partial class MainWindow : Window
{
    public MainWindow()
    {
        InitializeComponent();
        Loaded += MainWindow_Loaded;
    }

    private void MainWindow_Loaded(object sender, RoutedEventArgs e)
    {
        DrawSierpinski(new Point(0, 350), new Point(250, 0), new Point(500, 350), 4); // Adjust depth as needed
    }

    private void DrawSierpinski(Point p1, Point p2, Point p3, int depth)
    {
        if (depth == 0)
        {
            Polygon triangle = new Polygon();
            triangle.Points = new PointCollection { p1, p2, p3 };
            triangle.Stroke = Brushes.Black;
            triangle.Fill = Brushes.Black; // Or leave unfilled
            Sierpinski.Children.Add(triangle);
            return;
        }

        Point p1p2 = new Point((p1.X + p2.X) / 2, (p1.Y + p2.Y) / 2);
        Point p2p3 = new Point((p2.X + p3.X) / 2, (p2.Y + p3.Y) / 2);
        Point p3p1 = new Point((p3.X + p1.X) / 2, (p3.Y + p1.Y) / 2);

        DrawSierpinski(p1, p1p2, p3p1, depth - 1);
        DrawSierpinski(p1p2, p2, p2p3, depth - 1);
        DrawSierpinski(p3p1, p2p3, p3, depth - 1);
    }
}
```

