            // Create an HttpClientHandler with the certificate
            HttpClientHandler handler = new HttpClientHandler();
            handler.ClientCertificates.Add(clientCertificate);


            // Configure server certificate validation (important for security)
            // In production, validate the server certificate properly.  This example allows all server certs (for testing purposes only!)
            handler.ServerCertificateCustomValidationCallback = (message, cert, chain, errors) =>
            {
                // WARNING: This allows all certificates.  Only use for testing.
                // In production, properly validate the server certificate:
                //return errors == SslPolicyErrors.None; 
                return true; 
            };


            // Create an HttpClient with the handler
            using (HttpClient client = new HttpClient(handler))
            {
                // Create the content for the request
                StringContent content = new StringContent(jsonData, Encoding.UTF8, "application/json");

                // Send the POST request
                HttpResponseMessage response = await client.PostAsync(url, content);


                // Check the response status code
                if (response.IsSuccessStatusCode)
                {
                    // Read the response content
                    string responseBody = await response.Content.ReadAsStringAsync();
                    Console.WriteLine("POST request successful!");
                    Console.WriteLine("Response:\n" + responseBody);
                }
                else
                {
                    Console.WriteLine($"POST request failed with status code: {response.StatusCode}");
                    string errorResponse = await response.Content.ReadAsStringAsync();
                    Console.WriteLine($"Error Response:\n{errorResponse}");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }


        Console.WriteLine("Press any key to exit.");
        Console.ReadKey();
    }
}


